// ---------------------------------------------------------------------------
// One IMAP message -> the shape /ingest accepts.
//
// This file is plumbing. It does not decide whether an email is an offer or a
// request, who sent it, what a row means, or what anything costs. All of that
// is Python, where it is covered by tests. If you find yourself adding a rule
// about the trade here, it belongs on the other side of the wire.
// ---------------------------------------------------------------------------

const TENANT_ID = $env.TVD_TENANT_ID;
if (!TENANT_ID) {
  // Better to stop than to file a morning's mail against nothing. A missing
  // tenant makes /ingest answer 'unknown_tenant' for every message, and the
  // execution list fills with green ticks that moved no stock.
  throw new Error('TVD_TENANT_ID is not set on this n8n instance');
}

// Workbooks are sent whole and read on the backend by read_spreadsheet, the
// same function the sample corpus goes through. Everything else -- signature
// logos, PDFs, inline images -- is recorded by name only. Base64 inflates a
// file by a third, and a 2MB logo on every email is 2MB of nothing.
const WORKBOOK = /\.(xlsx|xlsm|xls)$/i;

// Reply quoting only. NOT forwarded messages: the client's entire workflow is
// forwarding a supplier's email to a collector mailbox, so the payload sits
// below 'Begin forwarded message' and cutting there would delete the email.
// The backend strips again and refuses any cut that removes more prices than
// it keeps, so this being imperfect is survivable.
const REPLY = [
  /^\s*(?:On|Am|Le|Il|El)\b[^\n]{0,160}\b(?:wrote|schrieb|a écrit|ha scritto):\s*$/im,
  /^\s*-{2,}\s*Original Message\s*-{2,}/im,
  /^>[^\n]*\n>[^\n]*\n>/m,
];
const FORWARD = /-{2,}\s*Forwarded message\s*-{2,}|Begin forwarded message/i;

function stripQuoted(body) {
  if (!body) return '';
  let cut = null;
  for (const pattern of REPLY) {
    const found = body.match(pattern);
    if (found && (cut === null || found.index < cut)) cut = found.index;
  }
  if (cut === null) return body;
  if (FORWARD.test(body.slice(cut))) return body;   // the forward is the point
  return body.slice(0, cut).trimEnd();
}

function address(raw) {
  const found = String(raw || '').match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
  return found ? found[0].toLowerCase() : '';
}

// The IMAP node's 'resolved' format hands back mailparser's output, whose shape
// has moved between versions: `from` is sometimes a string, sometimes
// {value:[{address,name}]}, and headers are sometimes a Map and sometimes a
// plain object. Read defensively rather than pick one and have the inbox go
// quiet after an n8n upgrade.
function headerOf(message, name) {
  const lower = name.toLowerCase();
  const headers = message.headers || {};

  if (typeof headers.get === 'function') {
    const viaMap = headers.get(lower);
    if (viaMap) return typeof viaMap === 'string' ? viaMap : JSON.stringify(viaMap);
  }
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === lower) {
      const value = headers[key];
      return typeof value === 'string' ? value : JSON.stringify(value);
    }
  }
  return '';
}

function fromField(message) {
  const raw = message.from;
  if (!raw) return { email: '', name: '' };
  if (typeof raw === 'string') {
    return { email: address(raw), name: raw.split('<')[0].replace(/"/g, '').trim() };
  }
  const first = (raw.value || [])[0] || {};
  return {
    email: String(first.address || address(raw.text) || '').toLowerCase(),
    name: String(first.name || '').trim(),
  };
}

function recipients(message) {
  const raw = message.to;
  if (!raw) return [];
  if (typeof raw === 'string') return [address(raw)].filter(Boolean);
  return (raw.value || []).map((v) => String(v.address || '').toLowerCase()).filter(Boolean);
}

// --------------------------------------------------------------------------
// Is this trade mail?
//
// The gate exists for privacy, not tidiness. Five mailboxes forward everything
// they receive, which includes the bank, the accountant, a recruiter and
// whatever a colleague sent to a work address. Deciding here means that mail
// never reaches the database at all.
//
// It has to be HERE and not on the backend. The pipeline stores an email
// BEFORE it classifies it -- save_email runs, then the classifier says 'this
// is not an offer' -- so a bank statement rejected by the backend is a bank
// statement stored in full, sitting in a review queue for someone to open.
//
// Deliberately loose. A supplier's price list that this drops is invisible:
// nobody knows to look for an email that never arrived. Junk that gets through
// costs a row and a model call. So when in doubt, let it through -- the
// backend's classifier is the second gate and it is much better at this.
// --------------------------------------------------------------------------

// What the trade puts in a subject line. WTS/WTB are universal; the rest cover
// the suppliers who write in full sentences.
const TRADE_SUBJECT =
  /\b(?:wts|wtb|wtt|rfq|offer|offers|stock|stocklist|price|pricelist|prices|list|quote|quotation|available|availability|angebot|lager|oferta|disponibil)\b/i;

// A spreadsheet is a price list often enough that the attachment alone is
// reason to keep the email, whatever the subject says.
const WORKBOOK_NAME = /\.(xlsx|xlsm|xls|csv)$/i;

// A body that quotes money against quantities. Catches the pasted WhatsApp
// offers, which frequently have no subject worth reading.
const MONEY = /(?:[€$£]\s?\d|\b\d+[.,]?\d*\s?(?:eur|usd|gbp|€|\$|£))/i;
const TRADE_WORD =
  /\b(?:iphone|samsung|galaxy|xiaomi|redmi|pixel|oppo|vivo|realme|honor|motorola|nokia|ipad|macbook|airpods|gb|tb)\b/i;

function decide(payload) {
  if (payload.attachments.some((a) => WORKBOOK_NAME.test(a.filename || ''))) {
    return { keep: true, why: 'spreadsheet attached' };
  }

  if (TRADE_SUBJECT.test(payload.subject || '')) {
    return { keep: true, why: 'trade wording in the subject' };
  }

  const body = payload.body_text || '';
  if (MONEY.test(body) && TRADE_WORD.test(body)) {
    return { keep: true, why: 'prices against product names in the body' };
  }

  return { keep: false, why: 'nothing in it looks like an offer or a request' };
}

const out = [];
const items = $input.all();

for (let index = 0; index < items.length; index += 1) {
  const item = items[index];
  const message = item.json;

  const text = message.textPlain || message.text || '';
  const html = message.textHtml || message.html || '';

  // Message-ID is what /ingest deduplicates on, and with five mailboxes
  // forwarding into one collector the same supplier email genuinely does
  // arrive twice. Gmail auto-forward and Outlook Redirect both preserve it.
  // The fallback is last-resort only: without something stable a redelivery
  // reconciles a second time and every row missing from the second copy is
  // closed as sold.
  const messageId =
    message.messageId ||
    headerOf(message, 'message-id') ||
    `<imap-${message.uid || index}-${Date.parse(message.date) || Date.now()}@tvd.local>`;

  const attachments = [];
  const binaries = item.binary || {};

  for (const key of Object.keys(binaries)) {
    const file = binaries[key];
    const filename = file.fileName || key;
    const record = {
      filename,
      mime_type: file.mimeType || '',
      kind: 'other',
      content_base64: null,
    };

    if (WORKBOOK.test(filename)) {
      // getBinaryDataBuffer rather than file.data: in filesystem binary mode
      // `.data` is an id, not the bytes, and reading it directly ships the
      // string 'filesystem-v2:...' to the backend as though it were a
      // spreadsheet. The helper works in both modes.
      let buffer = null;
      try {
        buffer = await this.helpers.getBinaryDataBuffer(index, key);
      } catch (error) {
        buffer = file.data ? Buffer.from(file.data, 'base64') : null;
      }
      if (buffer) record.content_base64 = buffer.toString('base64');
    }

    attachments.push(record);
  }

  const sender = fromField(message);

  const built = {
      tenant_id: TENANT_ID,
      message_id: messageId,
      in_reply_to: message.inReplyTo || headerOf(message, 'in-reply-to') || null,
      thread_id: null,
      direction: 'inbound',

      // The ORIGINAL sender, not the colleague who forwarded it -- Gmail
      // auto-forward and Outlook Redirect both leave From: untouched. When a
      // staff member forwards by hand instead, this is their address and the
      // backend falls through to reading the forwarded header block. That
      // fallback only works if the tenant's internal_domains lists the
      // client's own domain; leave it empty and every forwarded offer is filed
      // against the forwarder.
      from_email: sender.email,
      from_name: sender.name,
      to: recipients(message),
      subject: message.subject || '',
      received_at: new Date(message.date || Date.now()).toISOString(),

      // What gets parsed.
      body_text: stripQuoted(text || html.replace(/<[^>]+>/g, ' ')),
      // The complete original, for the source drawer. Never parsed, so it
      // keeps its markup -- that is what table extraction reads.
      body_raw: html || text,

      attachments,
  };

  // Not part of InboundEmail. The schema ignores unknown fields, so these ride
  // along harmlessly and make the IF node's decision readable in the execution
  // log -- which is the whole advantage of filtering here rather than in a
  // mailbox rule nobody can see afterwards.
  const { keep, why } = decide(built);
  built._keep = keep;
  built._why = why;

  out.push({ json: built });
}

return out;

// The backend replies with what it did -- 'processed as sell: 219 rows, 219
// inserted'. Surfacing it means a morning's execution list reads at a glance,
// instead of thirty identical green ticks that say nothing about whether any
// stock actually arrived.
for (const item of $input.all()) {
  const body = item.json || {};
  console.log(`${body.message_id || '(no id)'} -> ${body.detail || '(no detail)'}`);
}
return $input.all();
